function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 100000 characters.';
  if (!/^[a-z*]+$/.test(s)) return 's may contain only lowercase letters and *.';
  let balance = 0;
  for (const ch of s) {
    balance += ch === '*' ? -1 : 1;
    if (balance < 0) return 'Each * needs an unerased letter somewhere before it.';
  }
  return null;
}

