function clearStars(s) {
  // Follow the rules literally: at every '*' try erasing each copy of the smallest letter before it,
  // and keep the smallest final string (memoized on the current string).
  const memo = new Map();
  const finish = (t) => {
    const star = t.indexOf('*');
    if (star === -1) return t;
    if (memo.has(t)) return memo.get(t);
    let smallest = '{';
    for (let j = 0; j < star; j++) if (t[j] < smallest) smallest = t[j];
    let answer = null;
    for (let j = 0; j < star; j++) {
      if (t[j] !== smallest) continue;
      const result = finish(t.slice(0, j) + t.slice(j + 1, star) + t.slice(star + 1));
      if (answer === null || result < answer) answer = result;
    }
    memo.set(t, answer);
    return answer;
  };
  return finish(s);
}

