function generate(rand, size) {
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 12);
  const alphabet = size === 'large' || rand() < 0.2 ? 26 : 1 + Math.floor(rand() * 4);
  const starRate = rand() * 0.55;
  let letters = 0;
  let stars = 0;
  let s = '';
  for (let i = 0; i < n; i++) {
    // A '*' is only allowed while some letter before it is still unerased.
    if (letters > stars && rand() < starRate) {
      s += '*';
      stars++;
    } else {
      s += String.fromCharCode(97 + Math.floor(rand() * alphabet));
      letters++;
    }
  }
  return [s];
}
